node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const newAddress = {
  address1: '3201 Oakwood Drive',
  address2: '',
  city: 'Austin',
  state: 'TX',
  country: 'USA',
  zip: '78723'
};

db.prepare('UPDATE users SET address_json = ? WHERE user_id = ?').run(JSON.stringify(newAddress), 'maya_patel_731');

// Verify the update
const user = db.prepare('SELECT address_json FROM users WHERE user_id = ?').get('maya_patel_731');
console.log('Updated address:', user.address_json);
"
